use std::fs

fn find(ks: Vec<int>, k: int) -> int {
    let mut r: int = -1
    for i in 0..ks.len() {
        if ks[i] == k {
            r = i
        }
    }
    r
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap: int = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        if parts[0] == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i >= 0 {
                ks.remove(i)
                vs.remove(i)
            }
            ks.push(k)
            vs.push(v)
            if ks.len() > cap {
                let e = ks[0]
                ks.remove(0)
                vs.remove(0)
                println("evict ${e}")
            }
        } else if parts[0] == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(ks.clone(), k)
            if i < 0 {
                println("-1")
            } else {
                let v = vs[i]
                ks.remove(i)
                vs.remove(i)
                ks.push(k)
                vs.push(v)
                println("${v}")
            }
        } else if parts[0] == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut j = ks.len()
                while j > 0 {
                    j -= 1
                    out.push("${ks[j]}")
                }
                println(out.join(" "))
            }
        }
    }
}

